<?php
declare(strict_types=1);

session_start();

require_once __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/api/maketou.php';

$cartId =
    $_GET['cartId']
        ?? $_GET['cart_id']
            ?? $_GET['id']
                ?? null;

                if (!is_string($cartId) || $cartId === '') {
                    http_response_code(400);
                        exit('Identifiant de paiement manquant.');
                        }

                        try {

                            $cart = maketouGetCart($cartId);

                                $status = (string)(
                                        $cart['status']
                                                ?? ''
                                                    );

                                                        /*
                                                             * Statut Maketou officiel :
                                                                  *
                                                                       * waiting_payment
                                                                            * completed
                                                                                 * abandoned
                                                                                      * payment_failed
                                                                                           */

                                                                                               if ($status === 'completed') {

                                                                                                       /*
                                                                                                                * Le paiement est réellement confirmé.
                                                                                                                         *
                                                                                                                                  * On cherche la commande SOMBA
                                                                                                                                           * grâce au meta.orderId si disponible.
                                                                                                                                                    */

                                                                                                                                                            $orderId =
                                                                                                                                                                        $cart['meta']['orderId']
                                                                                                                                                                                    ?? $cart['meta']['order_id']
                                                                                                                                                                                                ?? null;

                                                                                                                                                                                                        if ($orderId !== null) {

                                                                                                                                                                                                                    $pdo = db();

                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                             * Mise à jour uniquement si la commande
                                                                                                                                                                                                                                                          * n'est pas déjà payée.
                                                                                                                                                                                                                                                                       */

                                                                                                                                                                                                                                                                                   $stmt = $pdo->prepare(
                                                                                                                                                                                                                                                                                                   "UPDATE orders
                                                                                                                                                                                                                                                                                                                    SET
                                                                                                                                                                                                                                                                                                                                        payment_status = 'paid',
                                                                                                                                                                                                                                                                                                                                                            payment_provider = 'maketou',
                                                                                                                                                                                                                                                                                                                                                                                payment_reference = :reference
                                                                                                                                                                                                                                                                                                                                                                                                 WHERE id = :id
                                                                                                                                                                                                                                                                                                                                                                                                                  AND (
                                                                                                                                                                                                                                                                                                                                                                                                                                      payment_status IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                          OR payment_status <> 'paid'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           )"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   $stmt->execute([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ':reference' => $cartId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ':id' => (int)$orderId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        * La livraison devient disponible.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $stmt = $pdo->prepare(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     "UPDATE orders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          SET delivery_status = 'pending'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WHERE id = ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AND (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            delivery_status IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    OR delivery_status NOT IN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ('delivered', 'processing')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 )"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $stmt->execute([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     (int)$orderId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 } catch (Throwable $e) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 error_log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '[SOMBA] Delivery status error: ' .
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         $e->getMessage()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ?>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <!doctype html>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <html lang="fr">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <head>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <meta charset="utf-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <meta
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     name="viewport"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     content="width=device-width,initial-scale=1"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <title>Paiement confirmé - SOMBA</title>
